// План specs/multi-tech-assignment.md 1.1–1.4 (кейсы .qa/tests/multi-tech-assignment/MT-01…MT-04). Admin, компания «test», десктоп.
// @writes: меняет настройку компании «Allow Multiple Techs» и создаёт работу «QA-AUTO multi-tech #80550f …».
// Исходное значение настройки запоминается в beforeAll и возвращается в afterAll; созданная работа переводится в Cancelled.
// Запросы send-sms перехватываются и обрываются, «Send SMS» не нажимается. Техники — только QA-Tech Alpha/Beta/Gamma.
import { test, expect } from '@playwright/test';
import { blockSmsSending, expectNoSmsSent, openDispatch, openNewJob } from '../dispatch-sms/dispatch-helpers';
import { cellValue } from '../admin-plans/plans-read-helpers';
import { jobRow, openJobsTab, setJobStatus } from '../job-closed-date/closed-helpers';
import {
  ADMIN_STATE, L, Lang, MULTI, TECHS,
  adminContext, allTechTags, expectLead, leadBadge, makeLeadButton, pickTech, prepare, readMultiTech, removeButton,
  setMultiTech, techCombo, techTag,
} from './multi-tech-helpers';

test.use({ storageState: ADMIN_STATE });
test.describe.configure({ mode: 'serial' });

const [ALPHA, BETA, GAMMA] = TECHS;
const LANGS: Lang[] = ['en', 'he'];

test.describe('Multiple technicians on one job (#80550f)', () => {
  let originalSetting: boolean | undefined;
  let smsHits: string[] = [];

  test.beforeAll(async ({ browser }, testInfo) => {
    const { context, page } = await adminContext(browser, testInfo);
    try {
      originalSetting = await readMultiTech(page);
    } finally {
      await context.close();
    }
  });

  // Вернуть «Allow Multiple Techs» как было до прогона (решение пользователя 14.10).
  test.afterAll(async ({ browser }, testInfo) => {
    if (originalSetting === undefined) return;
    const { context, page } = await adminContext(browser, testInfo);
    try {
      await setMultiTech(page, originalSetting);
    } finally {
      await context.close();
    }
  });

  test.afterEach(() => {
    expectNoSmsSent(smsHits);
  });

  test.describe('setting OFF', () => {
    test.beforeAll(async ({ browser }, testInfo) => {
      const { context, page } = await adminContext(browser, testInfo);
      try { await setMultiTech(page, false); } finally { await context.close(); }
    });

    for (const lang of LANGS) {
      const U = lang.toUpperCase();
      test(`Allow Multiple Techs OFF (${U}): Assign Technician keeps one technician - the second choice replaces the first in Job Info and Dispatch #80550f @desktop @writes`, async ({ page }) => {
        await prepare(page, lang);
        smsHits = await blockSmsSending(page);
        await openNewJob(page, lang);

        // Job Info: Alpha → Beta, остаётся только Beta (источник: «מה קיים» — בחירת טכנאי נוסף מחליפה את הקודם).
        const info = page.getByRole('tabpanel');
        const combo = techCombo(info, lang);
        await pickTech(page, combo, ALPHA.name);
        await expect(combo).toContainText(ALPHA.name);
        await pickTech(page, combo, BETA.name);
        await expect(combo).toContainText(BETA.name);
        await expect(combo).not.toContainText(ALPHA.name);
        await expect(leadBadge(info)).toHaveCount(0);
        await expect(info.getByText(MULTI.hint)).toHaveCount(0);

        // Dispatch: тот же один техник, получатель — только Beta.
        const dispatch = await openDispatch(page, lang);
        await expect(techCombo(dispatch, lang)).toContainText(BETA.name);
        await expect(techCombo(dispatch, lang)).not.toContainText(ALPHA.name);
        await expect(dispatch).toContainText(new RegExp(`${L[lang].recipient.source}\\s*${BETA.name}\\s*\\${BETA.phone}`));
        await expect(dispatch).not.toContainText(ALPHA.phone);
      });
    }
  });

  test.describe('setting ON', () => {
    test.beforeAll(async ({ browser }, testInfo) => {
      const { context, page } = await adminContext(browser, testInfo);
      try { await setMultiTech(page, true); } finally { await context.close(); }
    });

    for (const lang of LANGS) {
      const U = lang.toUpperCase();

      test(`Allow Multiple Techs ON (${U}): Job Info adds technicians as tags, the first is LEAD, "Make lead" moves LEAD, "Remove" drops a technician #80550f @desktop @writes`, async ({ page }) => {
        await prepare(page, lang);
        smsHits = await blockSmsSending(page);
        await openNewJob(page, lang);
        const info = page.getByRole('tabpanel');
        const combo = techCombo(info, lang);

        // Три техника не заменяют друг друга (источник: «מה רצוי» — לשבץ כמה טכנאים לעבודה אחת).
        for (const t of TECHS) await pickTech(page, combo, t.name);
        await expect(allTechTags(info)).toHaveCount(3);
        for (const t of TECHS) await expect(removeButton(techTag(info, t.name)), `${t.name} — «Remove»`).toBeVisible();

        // Первый — LEAD, подсказка про главного (комментарий программиста: первый = Lead).
        await expectLead(info, ALPHA.name, [BETA.name, GAMMA.name]);
        if (lang === 'en') await expect(info.getByText(MULTI.hint)).toBeVisible();

        // «Make lead» у Beta → LEAD переходит к Beta.
        await makeLeadButton(techTag(info, BETA.name)).click();
        await expectLead(info, BETA.name, [ALPHA.name, GAMMA.name]);

        // «Remove» у Gamma → остаются Alpha и Beta.
        await removeButton(techTag(info, GAMMA.name)).click();
        await expect(techTag(info, GAMMA.name)).toHaveCount(0);
        await expect(allTechTags(info)).toHaveCount(2);
        await expect(leadBadge(techTag(info, BETA.name))).toBeVisible();
      });

      test(`Allow Multiple Techs ON (${U}): Dispatch keeps all three technicians and lists all of them as SMS recipients, "Send SMS" enabled (not clicked) #80550f @desktop @writes`, async ({ page }) => {
        await prepare(page, lang);
        smsHits = await blockSmsSending(page);
        await openNewJob(page, lang);
        const dispatch = await openDispatch(page, lang);
        const combo = techCombo(dispatch, lang);

        for (const t of TECHS) await pickTech(page, combo, t.name);
        await expect(allTechTags(dispatch)).toHaveCount(3);
        await expectLead(dispatch, ALPHA.name, [BETA.name, GAMMA.name]);

        // Получатели — все назначенные (источник: «מה רצוי» — לשלוח SMS לכל הטכנאים המשובצים).
        const recipients = new RegExp(
          `${L[lang].recipient.source}\\s*` + TECHS.map((t) => `${t.name}\\s*\\${t.phone}`).join('\\s*'),
        );
        await expect(dispatch).toContainText(recipients);
        await expect(dispatch.getByRole('button', { name: L[lang].send })).toBeEnabled();
      });
    }

    test('Allow Multiple Techs ON (EN): saved job keeps all three technicians after reload and the Jobs list (Assigned) shows all of them in Technician #80550f @desktop @writes', async ({ page }) => {
      test.setTimeout(180_000);
      await prepare(page, 'en');
      smsHits = await blockSmsSending(page);
      const title = `QA-AUTO multi-tech #80550f ${Date.now().toString(36)}`;

      // New Job: клиент QA (адрес подставляется из карточки клиента), тип, описание, 3 техника → Create Job.
      await openNewJob(page, 'en');
      const info = page.getByRole('tabpanel');
      const client = page.getByLabel('Client Name *');
      await client.pressSequentially('QA-quota', { delay: 20 });
      await page.getByRole('button').filter({ hasText: 'QA-quota client' }).first().click();
      await expect(client).toHaveValue('QA-quota client');
      await expect(page.getByRole('textbox', { name: /^Address/ })).not.toHaveValue('');
      await page.getByRole('combobox').filter({ hasText: 'Select job type' }).click();
      await page.getByRole('option', { name: 'Repair', exact: true }).click();
      await page.getByLabel('Job Description').fill(title);
      const combo = techCombo(info, 'en');
      for (const t of TECHS) await pickTech(page, combo, t.name);
      await expect(allTechTags(info)).toHaveCount(3);
      await page.getByRole('button', { name: 'Create Job', exact: true }).click();
      await page.waitForURL(/\/JobDetail\?id=/, { timeout: 30_000 });
      const jobUrl = page.url().replace(/&tab=items/, '');
      const jobId = (await page.getByText(/^#JOB-\d+$/).first().innerText()).trim().slice(1);

      try {
        // Страница работы после перезагрузки: все 3, Alpha — LEAD (сохранено на сервере).
        await page.goto(jobUrl);
        const assign = page.locator('div')
          .filter({ has: page.getByText('Assign Technician', { exact: true }) })
          .filter({ hasText: MULTI.hint })
          .last();
        await expect(allTechTags(assign)).toHaveCount(3, { timeout: 20_000 });
        await expectLead(assign, ALPHA.name, [BETA.name, GAMMA.name]);

        // Jobs → Assigned: в колонке Technician все трое (источник: «מה רצוי» — להציג את כולם ברשימת העבודות).
        await openJobsTab(page, 'Assigned');
        await expect(jobRow(page, jobId)).toBeVisible();
        const techCell = await cellValue(page, jobRow(page, jobId), 'Technician');
        for (const t of TECHS) expect(techCell, `Technician у ${jobId}`).toContain(t.name);
      } finally {
        // Очистка: работа QA-AUTO → Cancelled (удаления работ в интерфейсе нет).
        await page.goto(jobUrl);
        await setJobStatus(page, 'Cancelled');
      }
    });
  });
});
